// Utility helpers for the checkout module.

// This function adds two numbers
function add(a, b) {
  // Return the result
  return a + b;
}

// This function formats a price
function formatPrice(amount, currency) {
  // Get the formatted string
  return new Intl.NumberFormat('id-ID', { style: 'currency', currency }).format(amount);
}

// Returns the store's calendar day for a date.
// The store runs on Asia/Jakarta time, so an order placed at 23:30 UTC
// is already the next day there. Do not use toISOString() for this.
function storeDay(date) {
  // Create the formatter
  const fmt = new Intl.DateTimeFormat('en-CA', { timeZone: 'Asia/Jakarta', year: 'numeric', month: '2-digit', day: '2-digit' });
  // Return the formatted day
  return fmt.format(date);
}

module.exports = { add, formatPrice, storeDay };

